<script setup>
import {computed,ref,watch,onMounted,onBeforeUnmount} from 'vue'
import {ElMessage} from 'element-plus'
import {Search,Refresh,ArrowDown,Menu,Document,Plus,ArrowLeft,Bell,QuestionFilled} from '@element-plus/icons-vue'
import Workbench from '@icon-park/vue-next/es/icons/Workbench'
import People from '@icon-park/vue-next/es/icons/People'
import Box from '@icon-park/vue-next/es/icons/Box'
import FactoryBuilding from '@icon-park/vue-next/es/icons/FactoryBuilding'
import ShoppingCart from '@icon-park/vue-next/es/icons/ShoppingCart'
import ConnectionPoint from '@icon-park/vue-next/es/icons/ConnectionPoint'
import Setting from '@icon-park/vue-next/es/icons/Setting'
import Truck from '@icon-park/vue-next/es/icons/Truck'
import Export from '@icon-park/vue-next/es/icons/Export'
import Order from '@icon-park/vue-next/es/icons/Order'
import AppWindowDialog from '../../../src/frontend/src/components/common/AppWindowDialog.vue'
import DesignTable from './DesignTable.vue'
import ReviewStock from './ReviewStock.vue'
import DispatchDesign from './DispatchDesign.vue'
const screens=[['metal-plan','D1 · 内部计划入口'],['metal','D1 · 金工半成品入库'],['dispatch-metal','D2 · 加工件直接外发'],['dispatch-semi','D2 · 公共未喷塑外发'],['dispatch-raw','D2 · 原管材整根外发'],['receipt-picker','D3 · 选择待回货外发单'],['receipt','D3 · 喷塑一次入库'],['receipt-zero','D3 · 整单零回货'],['detail','D4 · 外发单详情'],['history','D4 · 历史单据'],['stock','D5 · 公共半成品库存'],['records','D5 · 半成品入库记录'],['issue','D5 · 已喷塑与未喷塑领用'],['controls','通用控件与状态']]
const page=ref(location.hash.slice(1)||'metal'),dialog=ref(''),date=ref('2026-09-29'),returnDate=ref('2026-10-14'),warehouse=ref('半成品管材仓'),zone=ref('一楼 A区'),remark=ref(''),search=ref(''),state=ref('normal')
function navigate(next){if(next==='metal-picker'){dialog.value='metal-picker';return}page.value=next;location.hash=next;dialog.value='';state.value='normal'}
const onHash=()=>{const next=location.hash.slice(1);if(screens.some(s=>s[0]===next)){page.value=next;dialog.value='';ElMessage.closeAll()}}
onMounted(()=>addEventListener('hashchange',onHash));onBeforeUnmount(()=>removeEventListener('hashchange',onHash))
const inventoryPage=computed(()=>['stock','records','receipt','receipt-zero','receipt-picker','metal'].includes(page.value))
const nav=[['工作台',Workbench],['客户管理',People],['样品管理',Box],['产品管理',Box],['生产管理',FactoryBuilding],['采购管理',ShoppingCart],['生产车间',ConnectionPoint]]
const subnav=[['生产配置',Setting,''],['计划排产',Workbench,''],['内部计划',FactoryBuilding,'metal-plan'],['委外加工',Export,'detail'],['生产领料',Truck,'issue'],['工价方案',Box,''],['报工记录',Order,'']]
const metalRows=ref([
 {id:'front',part:'前腿管',material:'Q195',spec:'圆管 Φ22',thickness:'0.8',length:'650',color:'原料本色',required:2000,minimum:1200,received:400,sent:200,reserved:100,available:500,quantity:'300',operations:[['弯管',1400],['冲孔',1200]]},
 {id:'rear',part:'后腿管',material:'Q195',spec:'圆管 Φ22',thickness:'0.8',length:'720',color:'原料本色',required:2000,minimum:1000,received:200,sent:300,reserved:0,available:500,quantity:'200',operations:[['弯管',1000],['冲孔',1200]]},
 {id:'arm',part:'扶手管',material:'Q195',spec:'椭圆管 30×15',thickness:'0.9',length:'520',color:'原料本色',required:2000,minimum:800,received:400,sent:0,reserved:0,available:400,quantity:'',operations:[['弯管',800],['冲孔',900]]},
 {id:'join',part:'连接管',material:'Q195',spec:'圆管 Φ16',thickness:'0.7',length:'360',color:'原料本色',required:4000,minimum:1000,received:600,sent:0,reserved:0,available:400,quantity:'',operations:[['切管',1200],['冲孔',1000]]},
 {id:'back',part:'靠背管',material:'Q195',spec:'圆管 Φ19',thickness:'0.8',length:'880',color:'原料本色',required:2000,minimum:0,received:0,sent:0,reserved:0,available:0,quantity:'',operations:[['弯管',0],['冲孔',200]]}
])
const metalColumns=[['part','部位',100],['material','材质',72],['spec','规格',125],['thickness','厚度 mm',80],['length','切割长度 mm',98],['color','颜色',100],['required','订单需求',100,true],['minimum','最低报工',100,true],['received','已入库',90,true],['sent','已直发',90,true],['reserved','待发预留',90,true],['available','剩余可处理',100,true],['quantity','本次入库（支）',136]].map(([key,label,width,num])=>({key,label,width,num}))
const metalEnteredRows=computed(()=>metalRows.value.filter(r=>/^\d+$/.test(String(r.quantity).trim())&&Number.isSafeInteger(Number(r.quantity))&&Number(r.quantity)>0))
const metalTotal=computed(()=>metalEnteredRows.value.reduce((sum,r)=>sum+Number(r.quantity),0))
const selectedPart=ref(metalRows.value[0]);const number=n=>Number(n).toLocaleString('zh-CN')
const orderInfo=[['生产单号','SC20260929001'],['订单号','DD20260921001'],['排产单号','PC20260929001'],['订单量','1,000 把'],['入库人','当前仓管'],['产品名称','组合杯托折叠椅'],['品号','CP000128'],['货号','HT-806'],['订单颜色','黑色'],['加工状态','未喷塑']]
function warn(text){ElMessage.warning({message:text,duration:3000,grouping:true})}
function checkMetal(){
 for(const r of metalRows.value){
  const value=String(r.quantity).trim();
  if(value==='')continue;
  if(!/^\d+$/.test(value)||!Number.isSafeInteger(Number(value)))return warn(`${r.part}：请填写整数支数，不支持负数、小数或文字。`);
  if(Number(value)===0)continue;
  if(Number(value)>r.available)return warn(`${r.part}：本次最多可入${r.available}支，不能超量。`);
 }
 if(!metalEnteredRows.value.length)return warn('请至少填写一个大于0的入库数量。');
 if(!date.value||!warehouse.value||!zone.value)return warn('请填写收货日期、仓库和库区。');
 dialog.value='metal-confirm';
}
const dispatchSource=computed(()=>page.value.split('-')[1]||'metal')
const dispatchLabels={metal:'厂内已加工件',semi:'公共未喷塑半成品',raw:'公共原管材'}
watch(page,()=>{if(page.value==='receipt-zero')receiptRows.value.forEach(r=>{r.received='0';r.reason='本单无合格件回货'});else if(page.value==='receipt')resetReceipts()},{immediate:false})
const receiptRows=ref([])
function resetReceipts(){receiptRows.value=[{id:1,factory:'永盛喷塑厂',part:'前腿管',material:'Q195',spec:'圆管 Φ22',thickness:'0.8',length:650,sent:600,received:'590',reason:'表面涂层不均，少回10支',zone:'一楼 A区'},{id:2,factory:'华诚喷塑厂',part:'前腿管',material:'Q195',spec:'圆管 Φ22',thickness:'0.8',length:650,sent:400,received:'400',reason:'',zone:'一楼 A区'},{id:3,factory:'永盛喷塑厂',part:'后腿管',material:'Q195',spec:'圆管 Φ22',thickness:'0.8',length:720,sent:300,received:'280',reason:'外观划伤，少回20支',zone:'一楼 A区'},{id:4,factory:'华诚喷塑厂',part:'扶手管',material:'Q195',spec:'椭圆管 30×15',thickness:'0.9',length:520,sent:200,received:'0',reason:'本项无合格件回货',zone:'一楼 A区'},{id:5,factory:'永盛喷塑厂',part:'连接管',material:'Q195',spec:'圆管 Φ16',thickness:'0.7',length:360,sent:100,received:'100',reason:'',zone:'一楼 A区'}]}
resetReceipts();if(page.value==='receipt-zero')receiptRows.value.forEach(r=>{r.received='0';r.reason='本单无合格件回货'})
const receiptTotal=computed(()=>receiptRows.value.reduce((n,r)=>n+(Number(r.received)||0),0))
const receiptColumns=[['factory','加工厂',120],['product','产品',115],['part','部位',86],['material','材质',65],['spec','规格',108],['thickness','厚度 mm',68],['length','长度 mm',75],['origin','原状态',78],['color','喷塑颜色',80],['sent','实发（支）',90,true],['received','实收（支）',118],['difference','少回（支）',90,true],['reason','差额原因',228],['zone','入库库区',136]].map(([key,label,width,num])=>({key,label,width,num}))
function checkReceipt(){if(!date.value||!warehouse.value)return warn('请填写收货日期和仓库。');for(const r of receiptRows.value){if(r.received===''||!/^\d+$/.test(r.received))return warn(`${r.factory} · ${r.part}：请填写实收支数；没有回货须明确填写0。`);if(+r.received>r.sent)return warn(`${r.part}实收不能超过本厂实际发出${r.sent}支。`);if(+r.received<r.sent&&!r.reason.trim())return warn(`${r.part}少回${r.sent-Number(r.received)}支，请填写差额原因。`);if(+r.received>0&&!r.zone)return warn('请选择有实收明细的入库库区。')}dialog.value='receipt-confirm'}
function confirmDemo(){dialog.value='';ElMessage.success({message:'设计演示已完成，未保存业务单据或改变库存。',duration:3500})}
const planRows=[{id:1,product:'组合杯托折叠椅',code:'CP000128',order:'SC20260929001',schedule:'PC20260929001',quantity:1000,craft:'弯管、冲孔',due:'2026-10-08',progress:'60%',status:'进行中',wage:'工价已批准'}]
const planColumns=[['product','产品名称',210],['code','品号',120],['order','生产单号',180],['schedule','排产单号',180],['quantity','订单量（把）',110,true],['craft','厂内工艺',160],['due','金工完成日期',130],['status','作业状态',110],['progress','完成进度',110],['wage','工价状态',130],['action','操作',180]].map(([key,label,width,num])=>({key,label,width,num}))
const pickerColumns=[['number','外发单号',220],['source','材料来源',210],['schedule','排产单号',190],['factories','加工厂',260],['parts','部位数',100],['sent','实发（支）',140,true],['date','发出日期',160],['action','操作',120]].map(([key,label,width,num])=>({key,label,width,num}))
const pickerRows=[{id:1,number:'WF20260929001',source:'厂内已加工件',schedule:'PC20260929001',factories:'永盛喷塑厂、华诚喷塑厂',parts:4,sent:1600,date:'2026-09-29'},{id:2,number:'WF20260929002',source:'公共未喷塑半成品',schedule:'PC20260929002',factories:'永盛喷塑厂',parts:2,sent:600,date:'2026-09-29'}]
</script>
<template>
 <div class="shell"><aside class="sidebar"><div class="brand-logo">HiTree</div><div class="nav-list"><div v-for="[label,icon] in nav" :key="label" class="nav-item"><component :is="icon" theme="filled" size="20"/><span>{{label}}</span></div><div v-if="!inventoryPage"><a v-for="[label,icon,view] in subnav" :key="label" href="#" class="nav-item sub" :class="{active:(page==='metal-plan'&&view==='metal-plan')||(page.startsWith('dispatch')&&view==='detail')||(page==='detail'&&view==='detail')||(page==='issue'&&view==='issue')}" @click.prevent="view&&navigate(view)"><component :is="icon" theme="filled" size="20"/><span>{{label}}</span></a></div><div class="nav-item"><Truck theme="filled" size="20"/><span>仓库管理</span></div><template v-if="inventoryPage"><div class="nav-item sub"><Box theme="filled" size="20"/>成品库存</div><a class="nav-item sub active" href="#stock" @click.prevent="navigate('stock')"><Box theme="filled" size="20"/>材料库存</a><div class="nav-item sub"><Box theme="filled" size="20"/>库存预警</div></template></div><div class="nav-bottom"><div class="nav-item"><Setting theme="filled" size="20"/>权限管理</div><div class="nav-item"><Setting theme="filled" size="20"/>系统配置</div></div></aside>
 <header class="topbar"><ElIcon><Menu/></ElIcon><span class="crumb">{{inventoryPage?'仓库管理 / 半成品':'生产车间 / 管材加工'}}</span><span class="spacer"></span><span class="preview-note">{{['receipt-picker','receipt','receipt-zero','detail','history','stock','records','issue'].includes(page)?'旧稿待逐页修订 · 非本轮确认依据':'设计预览 · 示例数据 · 未接入业务'}}</span><ElSelect class="design-picker" :model-value="page" @update:model-value="navigate" aria-label="切换设计页面"><ElOption v-for="[value,label] in screens" :key="value" :value="value" :label="label"/></ElSelect><span>仓库管理员</span></header>
 <main class="main">
 <ReviewStock v-if="['detail','history','stock','records','issue'].includes(page)" :page="page" @navigate="navigate"/>
 <section v-else-if="page==='metal-plan'" class="design-page"><header class="page-heading"><div class="title-row"><h1>内部计划</h1><span class="muted">金工计划 · 1条产品计划</span></div></header><div class="tabs"><button class="tab active">金工计划</button><button class="tab">裁剪计划</button><button class="tab">车缝计划</button><button class="tab">装配计划</button></div><div class="filterbar"><ElInput class="search" :prefix-icon="Search" placeholder="搜索排产单号、生产单号、产品"/><span>金工完成日期</span><ElDatePicker type="daterange" start-placeholder="开始日期" end-placeholder="结束日期" range-separator="-"/><span class="spacer"></span><ElButton :icon="Refresh">刷新</ElButton></div><DesignTable :columns="planColumns" :rows="planRows" class="fill-table"><template #cell-status><span class="status info">进行中</span></template><template #cell-wage><span class="status success">工价已批准</span></template><template #cell-action><ElDropdown trigger="click"><ElButton link>更多<ElIcon><ArrowDown/></ElIcon></ElButton><template #dropdown><ElDropdownMenu><ElDropdownItem @click="navigate('metal')">半成品入库</ElDropdownItem><ElDropdownItem @click="navigate('dispatch-metal')">创建外发单</ElDropdownItem><ElDropdownItem divided @click="warn('沿用当前ERP报工入口。')">报工</ElDropdownItem><ElDropdownItem>生产领料</ElDropdownItem><ElDropdownItem>查看领料</ElDropdownItem><ElDropdownItem>工价方案</ElDropdownItem></ElDropdownMenu></template></ElDropdown></template></DesignTable><div class="pager"><span>共1条</span><ElSelect model-value="50条/页"><ElOption label="50条/页" value="50条/页"/></ElSelect><ElButton>1</ElButton></div></section>
 <section v-else-if="page==='metal'" class="design-page"><header class="page-heading"><div class="title-row"><h1>半成品入库</h1><span class="status">厂内金工</span></div><div class="actions"><ElButton @click="dialog='metal-picker'">选择金工计划</ElButton><ElButton :icon="Document" @click="navigate('records')">入库记录</ElButton></div></header>
 <section class="panel info-grid"><div v-for="[label,value] in orderInfo" :key="label" class="info-cell"><span>{{label}}</span><b>{{value}}</b></div></section>
 <section class="panel workspace"><div class="section-heading"><div><h2>本次入库</h2><span class="muted">填写大于0的支数即办理，空白或0不入库</span></div><ElButton :icon="Refresh" @click="warn('刷新后重新核对报工与可入库数量。')">刷新额度</ElButton></div><div class="field-grid"><label class="form-field required"><span>收货日期</span><ElDatePicker v-model="date" aria-label="收货日期" type="date" format="YYYY-MM-DD" value-format="YYYY-MM-DD" placeholder="选择日期"/></label><label class="form-field required"><span>仓库</span><ElSelect v-model="warehouse" aria-label="仓库"><ElOption label="半成品管材仓" value="半成品管材仓"/></ElSelect></label><label class="form-field required"><span>库区</span><ElSelect v-model="zone" aria-label="库区"><ElOption label="一楼 A区" value="一楼 A区"/><ElOption label="一楼 B区" value="一楼 B区"/></ElSelect></label><label class="form-field"><span>入库状态</span><ElInput model-value="未喷塑" disabled/></label></div>
 <DesignTable :columns="metalColumns" :rows="metalRows"><template #cell-minimum="{row}"><ElButton link @click="selectedPart=row;dialog='operations'">{{number(row.minimum)}}</ElButton></template><template #cell-available="{value}"><b :class="value?'brand':'muted'">{{number(value)}}</b></template><template #cell-quantity="{row}"><ElInput v-model="row.quantity" :aria-label="`${row.part}本次入库`" :disabled="!row.available" :placeholder="row.available?'0':'暂无可入'" inputmode="numeric"><template v-if="row.available" #suffix>支</template></ElInput></template></DesignTable>
 <div class="table-summary"><span>本次填写 <b>{{metalEnteredRows.length}}</b> 个部位</span><span>本次入库 <strong class="brand">{{number(metalTotal)}} 支</strong></span><span class="muted">点击“最低报工”可查看该部位的工序明细</span></div><div class="notice">本次只增加未喷塑半成品库存。已领原料不再扣减；入库与加工件直接外发共用剩余加工数量。</div><label class="form-field"><span>入库备注 <span class="muted">选填</span></span><ElInput v-model="remark" type="textarea" :rows="3" placeholder="填写本次收货或存放说明"/></label></section><footer class="footer-bar"><div>本次入库 <strong>{{number(metalTotal)}}</strong> 支<small>确认后可供下环节领用，也可选择未喷塑库存创建外发单。</small></div><ElButton @click="navigate('metal-plan')">返回</ElButton><ElButton @click="metalRows.forEach(r=>{r.quantity=''})">重填</ElButton><ElButton type="primary" @click="checkMetal">确认入库</ElButton></footer></section>
 <DispatchDesign v-else-if="page.startsWith('dispatch-')" :source="dispatchSource" @navigate="navigate"/>
 <section v-else-if="page==='receipt-picker'" class="design-page"><header class="page-heading"><div class="title-row"><h1>喷塑入库</h1><span class="muted">选择待回货外发单</span></div><ElButton @click="navigate('stock')">返回半成品</ElButton></header><div class="filterbar"><ElInput class="search" :prefix-icon="Search" placeholder="搜索外发单号、排产单号、加工厂"/><ElSelect placeholder="全部来源"><ElOption v-for="label in Object.values(dispatchLabels)" :key="label" :label="label" :value="label"/></ElSelect><ElButton :icon="Refresh">刷新</ElButton></div><DesignTable :columns="pickerColumns" :rows="pickerRows" class="fill-table"><template #cell-action><ElButton link @click="navigate('receipt')">办理入库</ElButton></template></DesignTable><div class="notice">仅显示可以办理最终回货的管材外发单。金工厂内入库请从“金工入库”选择内部计划。</div><div class="pager"><span>共2条</span><ElButton>1</ElButton></div></section>
 <section v-else-if="page==='receipt'||page==='receipt-zero'" class="design-page"><header class="page-heading"><div class="title-row"><h1>喷塑入库</h1><span class="status">外发入库</span><span class="status info">加工中</span></div><ElButton :icon="Document" @click="navigate('detail')">外发单详情</ElButton></header><section class="panel info-grid"><div class="info-cell"><span>外发单号</span><b>WF20260929001</b></div><div class="info-cell"><span>排产单号</span><b>PC20260929001</b></div><div class="info-cell"><span>材料来源</span><b>厂内已加工件</b></div><div class="info-cell"><span>加工厂</span><b>2 家</b></div><div class="info-cell"><span>实际发出</span><b>1,600 支</b></div><div class="info-cell"><span>产品</span><b>组合杯托折叠椅</b></div><div class="info-cell"><span>品号</span><b>CP000128</b></div><div class="info-cell"><span>订单量</span><b>1,000 把</b></div><div class="info-cell"><span>发出日期</span><b>2026-09-29</b></div><div class="info-cell"><span>入库状态</span><b>已喷塑</b></div></section><section class="panel workspace"><div class="section-heading"><div><h2>整单实际回货</h2><span class="muted">各厂、各部位逐行填写；没有回货请填0，不能留空</span></div></div><div class="field-grid"><label class="form-field required"><span>收货日期</span><ElDatePicker v-model="date" aria-label="收货日期" type="date" format="YYYY-MM-DD" value-format="YYYY-MM-DD" placeholder="选择日期"/></label><label class="form-field required"><span>入库仓库</span><ElSelect v-model="warehouse" aria-label="入库仓库"><ElOption label="半成品管材仓" value="半成品管材仓"/></ElSelect></label><label class="form-field"><span>默认库区</span><ElSelect v-model="zone" @change="receiptRows.forEach(r=>r.zone=zone)"><ElOption label="一楼 A区" value="一楼 A区"/><ElOption label="一楼 B区" value="一楼 B区"/></ElSelect></label><label class="form-field"><span>入库人</span><ElInput model-value="当前仓管" disabled/></label></div>
 <DesignTable :columns="receiptColumns" :rows="receiptRows"><template #cell-product>组合杯托折叠椅</template><template #cell-origin>未喷塑</template><template #cell-color>黑色</template><template #cell-received="{row}"><ElInput v-model="row.received" inputmode="numeric" :aria-label="`${row.factory}${row.part}实收`" placeholder="必填，可为0"><template #suffix>支</template></ElInput></template><template #cell-difference="{row}"><b :class="row.sent-Number(row.received)>0?'brand':''">{{row.received===''?'—':number(row.sent-Number(row.received))}}</b></template><template #cell-reason="{row}"><ElInput class="reason" v-model="row.reason" :disabled="row.received!==''&&Number(row.received)===row.sent" :placeholder="Number(row.received)===row.sent?'全回，无需填写':'少回须填写原因'" :aria-label="`${row.factory}${row.part}差额原因`"/></template><template #cell-zone="{row}"><ElSelect v-model="row.zone" :disabled="row.received==='0'" placeholder="选择库区"><ElOption label="一楼 A区" value="一楼 A区"/><ElOption label="一楼 B区" value="一楼 B区"/></ElSelect></template></DesignTable>
 <div class="table-summary"><span>实际发出 <b>1,600 支</b></span><span>本次实收 <strong>{{number(receiptTotal)}} 支</strong></span><span>少回差额 <strong class="brand">{{number(1600-receiptTotal)}} 支</strong></span><span>入库状态 <span class="status success">已喷塑</span></span></div><div class="notice warning"><b>整单只登记一次。</b> 确认后本单结束，差额保留在外发单；不能再补回或修改本次结果。{{receiptTotal===0?'本次整单实收0支，只记录结果，不增加库存。':''}}</div><label class="form-field"><span>入库备注 <span class="muted">选填</span></span><ElInput type="textarea" :rows="2" placeholder="填写整单收货说明"/></label></section><footer class="footer-bar"><div>本次实收 <strong>{{number(receiptTotal)}}</strong> 支<small>确认后增加实际收到的已喷塑库存，外发单同时结束。</small></div><ElButton @click="navigate('receipt-picker')">返回</ElButton><ElButton type="primary" @click="checkReceipt">核对并确认整单</ElButton></footer></section>
 <section v-else-if="page==='controls'" class="design-page"><header class="page-heading"><h1>控件与通用状态</h1><span class="muted">沿用现有ERP组件；仅供本套设计复核</span></header><section class="panel"><div class="section-heading"><h2>日期、下拉与输入框</h2></div><div class="field-grid"><label class="form-field"><span>单日期</span><ElDatePicker v-model="date" type="date" format="YYYY-MM-DD" value-format="YYYY-MM-DD"/></label><label class="form-field"><span>仓库下拉</span><ElSelect v-model="warehouse"><ElOption label="半成品管材仓" value="半成品管材仓"/><ElOption label="原料管材仓" value="原料管材仓"/></ElSelect></label><label class="form-field"><span>输入聚焦</span><ElInput model-value="200" aria-label="聚焦示例"/></label><label class="form-field"><span>禁用输入</span><ElInput model-value="已喷塑" disabled/></label></div><div class="section-separator"></div><div class="actions"><ElButton type="primary" @click="warn('不能超量，本次最多可入500支。')">气泡提示</ElButton><ElButton @click="dialog='operations'">查看工序窗口</ElButton><span class="status success">已喷塑</span><span class="status neutral">未喷塑</span></div></section><section class="panel"><div class="section-heading"><h2>页面状态</h2><ElSelect v-model="state" style="width:220px"><ElOption label="空数据" value="normal"/><ElOption label="加载中" value="loading"/><ElOption label="读取失败" value="error"/><ElOption label="无权限" value="forbidden"/><ElOption label="额度依据变化" value="stale"/><ElOption label="提交结果待核对" value="pending"/></ElSelect></div><ElSkeleton v-if="state==='loading'" :rows="4" animated/><ElAlert v-else-if="state==='error'" title="读取失败，请重试。" type="error" :closable="false"><ElButton @click="state='normal'">重试</ElButton></ElAlert><ElAlert v-else-if="state==='forbidden'" title="当前账号没有此操作权限，请联系管理员配置。" type="warning" :closable="false"/><ElAlert v-else-if="state==='stale'" title="报工或数量占用已变化，请刷新后重新核对本次填写。" type="warning" :closable="false"><ElButton @click="state='normal'">刷新额度</ElButton></ElAlert><ElAlert v-else-if="state==='pending'" title="提交结果尚未确认，请核对本次提交，避免重复入库。" type="warning" :closable="false"><ElButton @click="confirmDemo">核对本次提交</ElButton></ElAlert><div v-else class="loading-sample"><span class="muted">暂无可办理的单据，请确认相关工序已报工或外发单已发出。</span></div></section></section>
 </main></div>
 <AppWindowDialog :model-value="dialog==='operations'" @update:model-value="dialog=''" :title="`${selectedPart.part} · 加工完成依据`" :width="820"><div class="info-grid"><div class="info-cell"><span>工价方案</span><b>GJ20260929001 · V2</b></div><div class="info-cell"><span>状态</span><b>已批准</b></div><div class="info-cell"><span>计量单位</span><b>支</b></div></div><DesignTable :columns="[{key:'operation',label:'必需工序',width:250},{key:'reported',label:'有效累计报工（支）',width:210,num:true},{key:'basis',label:'完成依据',width:240}]" :rows="selectedPart.operations.map(([operation,reported])=>({operation,reported,basis:reported===selectedPart.minimum?'最低值':'已累计多人、多次报工'}))"/><div class="notice">可确认的加工完成量 <b>{{number(selectedPart.minimum)}}支</b>；已入库{{number(selectedPart.received)}}支，已直发{{number(selectedPart.sent)}}支，待发预留{{number(selectedPart.reserved)}}支，剩余可处理 <b>{{number(selectedPart.available)}}支</b>。</div><template #footer><ElButton @click="dialog=''">关闭</ElButton></template></AppWindowDialog>
 <AppWindowDialog :model-value="dialog==='metal-picker'" @update:model-value="dialog=''" title="选择内部金工计划" :width="1260"><div class="filterbar"><ElInput class="search" :prefix-icon="Search" placeholder="搜索生产单号、排产单号或产品"/><ElButton>查询</ElButton></div><DesignTable :columns="planColumns.filter(c=>!['craft','progress','wage'].includes(c.key))" :rows="planRows"><template #cell-action><ElButton link @click="navigate('metal')">选择并入库</ElButton></template></DesignTable><template #footer><ElButton @click="dialog=''">取消</ElButton></template></AppWindowDialog>
 <AppWindowDialog :model-value="['metal-confirm','receipt-confirm'].includes(dialog)" @update:model-value="dialog=''" :title="dialog==='receipt-confirm'?'确认整单回货并结束外发单':'确认金工半成品入库'" :width="900"><template v-if="dialog==='receipt-confirm'"><div class="info-grid"><div class="info-cell"><span>外发单号</span><b>WF20260929001</b></div><div class="info-cell"><span>实际发出</span><b>1,600 支</b></div><div class="info-cell"><span>加工厂</span><b>2 家</b></div></div><DesignTable :columns="[{key:'factory',label:'加工厂',width:200},{key:'sent',label:'发出（支）',width:180,num:true},{key:'received',label:'实收（支）',width:180,num:true},{key:'difference',label:'少回（支）',width:180,num:true}]" :rows="['永盛喷塑厂','华诚喷塑厂'].map(factory=>{const rows=receiptRows.filter(r=>r.factory===factory);return {factory,sent:rows.reduce((n,r)=>n+r.sent,0),received:rows.reduce((n,r)=>n+Number(r.received),0),difference:rows.reduce((n,r)=>n+r.sent-Number(r.received),0)}})"/><div class="notice warning">确认后实收 <b>{{number(receiptTotal)}}支</b> 入已喷塑半成品库，少回 <b>{{number(1600-receiptTotal)}}支</b> 留在原单。<br>本单全部加工厂、全部部位一起结束，之后不能追加回货或修改。{{receiptTotal===0?'本次不增加库存。':''}}</div></template><template v-else><p>本次将{{metalEnteredRows.length}}个部位、<b>{{number(metalTotal)}}支</b>入{{warehouse}}／{{zone}}，状态为未喷塑。</p><div class="notice">已领原料不重复扣减。提交时再次核对报工及剩余额度。</div></template><template #footer><ElButton @click="dialog=''">返回检查</ElButton><ElButton type="primary" @click="confirmDemo">{{dialog==='receipt-confirm'?'确认入库并结束':'确认入库'}}</ElButton></template></AppWindowDialog>
</template>
